  -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 16px); mask-image: linear-gradient(to bottom, transparent 0, #000 16px); }
._td_wl_line { display: flex; align-items: flex-start; gap: 8px; padding: 6px 6px 5px 4px; border-left: 2px solid transparent; border-bottom: 1px solid #f1f5f9; }
._td_wl_ic { flex: 0 0 14px; text-align: center; font: 800 12px/15px 'Inter', sans-serif; }
