._td_wl_top { display: flex; align-items: baseline; gap: 8px; }
._td_wl_sec { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 700 11.5px/15px 'Inter', sans-serif; color: #0d1b2a; }
._td_wl_act { flex: none; font: 800 9px/15px 'Inter', sans-serif; letter-spacing: .08em; text-transform: uppercase; color: #64748b; }
._td_wl_act_accept, ._td_wl_act_format { color: #15803d; }
._td_wl_act_counter { color: #8a6d12; }
._td_wl_act_reject { color: #b42318; }
._td_wl_act_miss { color: #b45309; }
._td_wl_sum { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 500 11.5px/1.35 'Inter', sans-serif; color: #475569; }
._td_wl_wait { opacity: .45; }
._td_wl_now, ._td_wl_cur { background: #fffaeb; border-left-color: #c9a227; }
._td_wl_writing ._td_wl_act { color: #94a3b8; }
._td_spin_sm { width: 7px; height: 7px; border-width: 1.5px; border-color: #e2e8f0; border-top-color: #94a3b8; }
._td_wl_why { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 500 11px/1.35 'Inter', sans-serif; color: #8a6d12; }
._td_wl_art { padding: 8px 4px 3px; font: 800 9px/1 'Inter', sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #64748b; }
._td_wl_sum del, ._td_wl_sum ins { font-weight: 600; }
._td_wl_done ._td_wl_ic { color: #15803d; }
._td_wl_warn { cursor: pointer; }
._td_wl_warn ._td_wl_ic { color: #b45309; }
._td_wl_warn:hover { background: #fff7ed; }
._td_wl_skip { opacity: .55; }
._td_wdone { margin-top: 8px; }
._td_wdone > summary { cursor: pointer; list-style: none; font: 600 11.5px/1.4 'Inter', sans-serif; color: #475569; }
._td_wdone > summary::-webkit-details-marker { display: none; }
._td_wdone > summary::before { content: "▸ "; color: #8a6d12; }
._td_wdone[open] > summary::before { content: "▾ "; }
._td_wl_all { max-height: 260px; margin-top: 6px; padding-bottom: 0; -webkit-mask-image: none; mask-image: none; }
._td_next { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
._td_next_b { display: flex; flex-direction: column; gap: 3px; text-align: left; padding: 11px 12px; background: #fff; border: 1px solid #e2e8f0; border-top: 2px solid #c9a227; cursor: pointer; font: inherit; }
._td_next_b:hover { border-color: #e9d38a; background: #fffdf6; }
._td_next_t { font: 700 13px/1.3 'Inter', sans-serif; color: #0d1b2a; }
._td_next_s { font: 500 11px/1.4 'Inter', sans-serif; color: #64748b; }
._td_for { margin: 2px 0 6px; }
._td_table { width: 100%; border-collapse: collapse; margin-top: 8px; font: 500 11.5px/1.45 'Inter', sans-serif; color: #1e293b; }
._td_table th { text-align: left; font: 700 9px/1.2 'Inter', sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #fff; background: #0d1b2a; padding: 6px 7px; }
._td_table td { vertical-align: top; padding: 6px 7px; border-bottom: 1px solid #eef2f6; }
._td_table tr:nth-child(even) td { background: #fbfcfd; }

/* [SEND-CHECK] Before you send. A verdict, then the items by kind; the
   dot says how much each matters (red fix, amber look, slate info). */
._sc_banner { padding: 13px 14px 13px; background: #fff; border: 1px solid #e2e8f0; border-top: 3px solid #c9a227; }
._sc_banner_fix { border-top-color: #b42318; }
._sc_banner_ok { border-top-color: #15803d; }
._sc_verdict { font: 800 17px/1.3 'Inter', sans-serif; color: #0d1b2a; margin-bottom: 6px; }
._sc_banner_fix ._sc_verdict { color: #7f1d1d; }
._sc_banner_ok ._sc_verdict { color: #14532d; }
._sc_counts { display: flex; flex-wrap: wrap; gap: 6px 14px; font: 600 11.5px/1.3 'Inter', sans-serif; color: #475569; }
._sc_cnt { display: inline-flex; align-items: center; gap: 6px; }
._sc_dot { display: inline-block; flex: 0 0 auto; width: 8px; height: 8px; border-radius: 50%; }
._sc_dot_fix { background: #b42318; }
._sc_dot_look { background: #d97706; }
._sc_dot_fyi { background: #94a3b8; }
._sc_banner_acts { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 11px; }
._sc_row { display: flex; gap: 10px; align-items: flex-start; padding: 9px 11px; margin: 0 0 6px; background: #fff; border: 1px solid #e2e8f0; }
._sc_row ._sc_dot { margin-top: 5px; }
._sc_row_closed { opacity: .6; }
._sc_main { flex: 1 1 auto; min-width: 0; }
._sc_title { font: 700 12.5px/1.35 'Inter', sans-serif; color: #0d1b2a; }
._sc_ai { font: 700 8.5px/1 'Inter', sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #8a6d12; border: 1px solid #e9d38a; padding: 2px 5px; margin-left: 7px; vertical-align: 2px; }
._sc_detail { font: 500 11.5px/1.45 'Inter', sans-serif; color: #475569; margin-top: 2px; word-wrap: break-word; }
._sc_quote { font: 400 12px/1.5 Georgia, 'Times New Roman', serif; color: #3a2f0e; margin-top: 5px; padding-left: 8px; border-left: 2px solid #e9d38a; word-wrap: break-word; }
._sc_acts { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-top: 7px; }
._sc_fix { font: 700 10.5px/1 'Inter', sans-serif; padding: 6px 10px; border: 1px solid #0d47a1; color: #fff; cursor: pointer; background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%); }
._sc_fix:disabled { opacity: .5; cursor: default; }
._sc_ignb { background: none; border: 0; padding: 2px 0; font: 600 11px/1.2 'Inter', sans-serif; color: #64748b; cursor: pointer; }
._sc_ignb:hover { color: #0d1b2a; text-decoration: underline; }
._sc_done { font: 700 11px/1.2 'Inter', sans-serif; color: #15803d; }
._sc_ign { font: 600 11px/1.2 'Inter', sans-serif; color: #94a3b8; }

/* [TD-WAIT] The wait while their changes are weighed: A · Workbench with C's clock and ring. */
._tw { margin: 0 0 12px; font-family: 'Inter', 'Segoe UI', sans-serif; color: #0f1f3a; }
._tw_clock { font: 700 13px/1 'Inter', sans-serif; font-variant-numeric: tabular-nums; letter-spacing: .02em; }
._tw_empty { padding: 10px 0 4px; font: italic 500 11.5px/1.45 'Inter', sans-serif; color: #64748b; }
._tw_dec { display: flex; align-items: baseline; gap: 8px; padding: 6px 0; border-top: 1px solid #f1f5f9; }
._tw_new { animation: _tw_in .35s ease-out both; }
._tw_dec_live ._tw_dec_t { font-style: italic; color: #64748b; }
._tw_dec_t { min-width: 0; font: 500 12px/1.45 'Inter', sans-serif; color: #334155; }
._tw_dec_s { display: block; font: 600 9.5px/1.5 'Inter', sans-serif; letter-spacing: .06em; text-transform: uppercase; color: #94a3b8; }
@keyframes _tw_in { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
@keyframes _tw_pulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(201, 162, 39, .45); } 50% { box-shadow: 0 0 0 5px rgba(201, 162, 39, 0); } }
@keyframes _tw_sheen { from { background-position: -160px 0; } to { background-position: 160px 0; } }

/* A · Workbench */
._tw_a { background: #fff; border: 1px solid #e2e8f0; }
._tw_band { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; justify-content: space-between; padding: 10px 13px; background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%); color: #fff; }
._tw_title { font: 700 13.5px/1.2 Georgia, serif; }
._tw_band ._tw_clock { color: #f2d866; }
._tw_bar { height: 3px; background: #e2e8f0; }
._tw_bar i { display: block; height: 100%; background: #c9a227; transition: width .4s ease; }
._tw_steps { list-style: none; margin: 0; padding: 10px 13px 4px; display: flex; flex-direction: column; gap: 7px; }
._tw_step { display: grid; grid-template-columns: 14px 130px 1fr; align-items: baseline; gap: 6px; font-size: 12px; }
._tw_mark { width: 9px; height: 9px; border-radius: 50%; border: 1.5px solid #cbd5e1; transform: translateY(1px); }
._tw_done ._tw_mark { background: #c9a227; border-color: #c9a227; }
._tw_now ._tw_mark { background: #0d1b2a; border-color: #c9a227; animation: _tw_pulse 1.6s ease-in-out infinite; }
._tw_name { font-weight: 700; color: #0f1f3a; }
._tw_detail { color: #64748b; }
._tw_spot { margin: 8px 13px 2px; padding: 9px 11px; border-left: 3px solid #c9a227; background: #fffbeb; }
._tw_spot_h { font: 700 9.5px/1.4 'Inter', sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #8a6d12; }
._tw_spot_h span { margin-left: 6px; font-weight: 600; color: #a0864a; letter-spacing: .02em; text-transform: none; }
._tw_spot_s { margin-top: 3px; font: 600 11.5px/1.4 'Inter', sans-serif; color: #334155; }
._tw_spot_q { margin-top: 3px; font: 12.5px/1.5 Georgia, serif; color: #0f1f3a; }
._tw_feed { padding: 10px 13px 8px; }
._tw_feed_list { margin-top: 4px; overflow-y: auto; overscroll-behavior: contain; }
._tw_next ._tw_mark { border-style: dashed; }
._tw_short ._tw_steps { display: none; }
._tw_short ._tw_spot_q { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
._tw_tiny ._tw_spot { display: none; }
._tw_feed_h { font: 700 9.5px/1.4 'Inter', sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #64748b; }
._tw_feed_h span { margin-left: 6px; color: #0f1f3a; letter-spacing: .02em; }
._tw_head { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
._tw_sub { font: 500 10.5px/1.3 'Inter', sans-serif; color: #cbd5e1; }
._tw_time { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
._tw_ring { width: 30px; height: 30px; }
._tw_band ._tw_clock { font: 700 21px/1 Georgia, serif; color: #f2d866; letter-spacing: 0; }
/* [TD-RETYPED] a heading they retyped without tracking it */
._td_retyped { margin: 6px 0 2px; padding: 6px 9px; font: 500 11.5px/1.45 'Inter', sans-serif; color: #7c5e10; background: #fffbeb; border-left: 3px solid #c9a227; }


/* [TD-YOUR-CALL-GROUP] the changes left to you: together, gold-marked, a pinned count */
._td_callstrip { position: sticky; top: 0; z-index: 6; display: flex; align-items: center; gap: 8px; margin: 0 0 8px; padding: 7px 12px;
  background: #fffbea; border: 1px solid #e9d38a; border-left: 3px solid #c9a227; font: 600 12px/1.3 'Inter', sans-serif; color: #5c4708; }
._td_callstrip_n { font-weight: 800; color: #8a6d12; }
._td_callstrip_go { margin-left: auto; }
._td_callgroup > ._eg_group_header { color: #8a6d12; border-bottom-color: #e9d38a; }
/* [TD-CALL-LOOK] a card ELI left to you: the gold edge wherever it shows — in the group or under a filter, answered or not */
._td_card._td_card_call { border-left-color: #c9a227; background: #fffdf6; }
._td_call_sec { font: 700 10px/1.3 'Inter', sans-serif; letter-spacing: .06em; text-transform: uppercase; color: #64748b; margin: 8px 0 3px; }
/* [TD-GO] Anything a click takes to its place in Word: marked on hover by the panel's one item click (_tdWireGo). */
._td_go { cursor: pointer; }
/* [TD-NO-PINS] the item is the way to Word: a faint gold outline on hover, a gold ring on keyboard focus */
._td_go:hover { outline: 1px solid rgba(201, 162, 39, .45); outline-offset: -1px; }
[data-td-gokey]:focus-visible { outline: 2px solid #c9a227; outline-offset: 1px; }

/* [PRECEDENT] What colleagues did before: a quiet block under Why; Strong carries the gold rule. */
._td_prec { margin-top: 7px; padding: 6px 9px; background: #f8fafc; border-left: 3px solid #cbd5e1; font: 500 11.5px/1.45 'Inter', sans-serif; color: #334155; }
._td_prec_strong { background: #fffbeb; border-left-color: #c9a227; }
._td_prec_single { color: #64748b; }
._td_prec_head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 7px; width: 100%; padding: 0; border: 0; background: none; font: inherit; color: inherit; text-align: left; cursor: pointer; }
._td_prec_k { font: 700 9px/1 'Inter', sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #8a6d12; }
._td_prec_single ._td_prec_k { margin-right: 4px; color: #64748b; }
._td_prec_lvl { font: 700 9px/1 'Inter', sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #334155; }
._td_prec_strong ._td_prec_lvl { color: #8a6d12; }
._td_prec_n { font-weight: 600; color: #0f172a; }
._td_prec_more { margin-left: auto; font: 600 10.5px/1.3 'Inter', sans-serif; color: #92400e; text-decoration: underline dotted; text-underline-offset: 2px; }
._td_prec_bar { display: flex; height: 4px; margin: 6px 0 3px; background: #e2e8f0; }
._td_prec_b_accepted { background: #15803d; }
._td_prec_b_countered { background: #c9a227; }
._td_prec_b_rejected { background: #b42318; }
._td_prec_legend { font-size: 10.5px; color: #64748b; }
._td_prec_ex { margin: 7px 0 0; padding-left: 16px; }
._td_prec_ex li { margin: 3px 0; }
._td_prec_conf, ._td_prec_who { font-size: 10.5px; color: #64748b; }
._td_prec_src { margin-top: 7px; padding-top: 6px; border-top: 1px solid #e2e8f0; font-size: 10.5px; color: #64748b; }
._td_prec_src b { font-weight: 700; color: #0f172a; }

/* ─── [AGENT-LAYOUT] Agent screens in the chat: full width, rows not boxes, one scroll (Iris's layout, 10-21) ─── */
._eg_body_chat { padding: 10px 10px 0; font-size: 14px; }
._eg_body_chat ._eg_actions_sticky._eg_actions_pin { margin: 4px -10px 0; padding: 10px; }
/* [CARDS] a change's card as Respond draws its own (the owner, 10-22: "make the cards look how they do in Respond"): a
   white card, a thin border, a coloured left edge (gold on one to double-check); the clause title in the team screen's
   Georgia, the section heading over each group its gold small caps; the clause unframed; WHY a small gold label; the
   buttons under it. No tags, no inner boxes. */
._eg_body_chat ._eg_group_header { font: 700 10.5px/1.4 'Segoe UI', system-ui, sans-serif; letter-spacing: .15em; text-transform: uppercase; color: #8a6a00; }
._eg_body_chat ._eg_group_count { font-weight: 600; color: #a08c4a; }
._eg_body_chat ._eg_card { position: relative; margin: 0 0 8px; padding: 10px 12px 11px; background: #fff; border: 1px solid #e2e8f0; border-left: 3px solid #94a3b8; box-shadow: none; }
._eg_body_chat ._eg_card:hover { box-shadow: 0 1px 7px rgba(15, 31, 58, .08); }
._eg_body_chat ._eg_card_review { border-left-color: #c9a227; background: #fffdf6; }
._eg_body_chat ._eg_card_applied { border-left-color: #15803d; }
._eg_body_chat ._eg_card_rejected { border-left-color: #cbd5e1; opacity: .72; }
._eg_body_chat ._eg_card_loc { margin: 0 0 6px; padding: 0 96px 0 0; background: none; border: 0; }
._eg_body_chat ._eg_card_loc_section { font: 400 15.5px/1.3 Georgia, serif; color: #0f1f3d; }
._eg_body_chat ._eg_card_top { position: absolute; top: 10px; right: 12px; }
._eg_body_chat ._eg_type_badge, ._eg_body_chat ._eg_card_category { display: none; }
._eg_body_chat ._eg_inline_diff { padding: 0; background: none; border: 0; }
._eg_body_chat ._eg_card_rationale { margin-top: 7px; padding-top: 0; border-top: 0; }
._eg_body_chat ._eg_card_why { padding: 0; border: 0; background: none; font: 700 9px/1.6 Inter, 'Segoe UI', system-ui, sans-serif; letter-spacing: .12em; color: #8a6d12; }
._eg_body_chat ._eg_card_why_text { font: 500 12px/1.5 Inter, 'Segoe UI', system-ui, sans-serif; color: #334155; }
._eg_body_chat ._eg_card_actions { margin-top: 9px; padding-top: 0; border-top: 0; }
/* [DOUBLE-CHECK] the badge: gold outline to double-check (Apply all includes it); amber to check first (it doesn't) */
._eg_body_chat ._eg_card_review_pill { padding: 2px 7px; border: 1px solid #c9a227; border-radius: 0; background: transparent; font: 700 9.5px/1.3 Inter, 'Segoe UI', system-ui, sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #8a6d0f; }
._eg_body_chat ._eg_card_review_pill._eg_pill_first { border-color: #d97706; background: #fef3c7; color: #92400e; }
/* the mini-map column goes: the list is the page */
._eg_body_chat ._eg_review_main { display: block; }
._eg_body_chat ._eg_minimap { display: none; }
/* one scroll: no box scrolls inside the page */
._eg_body_chat ._td_wl, ._eg_body_chat ._td_wl_all, ._eg_body_chat ._eg_draft_preview, ._eg_body_chat ._eg_draft_text, ._eg_body_chat ._td_askdlg ._td_ask { max-height: none; overflow: visible; }
._eg_body_chat ._td_wl { padding-bottom: 0; -webkit-mask-image: none; mask-image: none; }
/* [BOX] the writing list in the team's box: the bar and totals pinned, the list scrolling under them */
._eg_team ._td_inbox { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; padding: 10px 12px 0; }
._eg_team ._td_inbox ._td_wl { flex: 1 1 auto; min-height: 0; max-height: none; overflow-y: auto; padding-bottom: 60px;
  -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 16px); mask-image: linear-gradient(to bottom, transparent 0, #000 16px); }
/* the house rules: squared corners (the question chips and their number, the "Why?" pill, the card buttons); Reject platinum */
._eg_clar_opt, ._eg_clar_n, ._eg_card_why, ._eg_card_btn { border-radius: 0; }
._eg_card_reject { background: linear-gradient(180deg, #ffffff 0%, #e8edf2 100%); border-color: #b0bcc6; color: #0d1b2a; }
._eg_card_reject:hover:not(:disabled) { background: linear-gradient(180deg, #ffffff 0%, #dde3ea 100%); border-color: #94a3b8; color: #0f172a; }
/* Iris's part-1 fixes (10-21): no internal paragraph line or confidence dots on a card. The page says each thing once:
   YOUR TURN and the counts in the banner, Apply all only in the pinned bar; the pills and the help line go. */
._eg_body_chat ._eg_card_loc_para, ._eg_body_chat ._eg_card_dots { display: none; }
._eg_body_chat ._eg_turn, ._eg_body_chat ._eg_review_stats, ._eg_body_chat ._eg_prop_hint, ._eg_body_chat ._eg_prop_head button { display: none; }

/* [TEAM] the agent team over a run's waiting screens (tools/eli_team draws it) */
._eg_team { margin: 0 0 10px; }
/* [TEAM-FIT] the team's screen alone fills the pane under the band, edge to edge (its height set to what the pane
   shows); light in both of ELI's modes, the header alone navy (the owner, 10-22) */
._eg_body_chat._eg_body_team { padding-bottom: 0; }
._eg_body_team > ._eg_team { margin: 0 -10px; }
._eg_body_chat._eg_body_team > ._eg_band { margin-bottom: 0; background: #f5f7fa; }
/* [CARD-EDIT] Edit beside Apply / Reject, platinum like Reject (it opens the clause in place: [IN-PLACE] below) */
._eg_card_edit_b { background: linear-gradient(180deg, #ffffff 0%, #e8edf2 100%); border-color: #b0bcc6; color: #0d1b2a; }
._eg_card_edit_b:hover:not(:disabled) { background: linear-gradient(180deg, #ffffff 0%, #dde3ea 100%); border-color: #94a3b8; }
/* gold, not amber, for what needs you; no gap left where the pills and YOUR TURN were */
._eg_body_chat ._eg_nd_box { border-color: #c9a227; border-left-color: #c9a227; background: #fffdf5; }
._eg_body_chat ._eg_nd_head, ._eg_body_chat ._eg_nd_row b, ._eg_body_chat ._eg_nd_sub { color: #13294b; }
._eg_body_chat ._eg_card_audit { border-left-color: #c9a227; }
/* [LOOK-LABEL] a new clause's look: the plan's, then Word's read back (⚠ in red where Word shows otherwise) */
._eg_body_chat ._eg_card_audit._eg_card_look { border-left-color: #94a3b8; }
._eg_body_chat ._eg_card_audit._eg_look_bad { border-left-color: #b42318; color: #7a1f17; }
._eg_body_chat ._eg_rv:has(> ._eg_review_stats) { display: none; }
/* ─── [BAND] the run's top band, pinned (Iris's layout, 10-21); the old title bar, strip and INSTRUCTION box give way;
   the screen's last action row pinned at the bottom ─── */
._eg_body_chat { padding-top: 0; }
._eg_body_chat > ._eg_band { position: sticky; top: 33px; z-index: 7; margin: 0 -10px 10px; padding: 5px 10px 5px; background: #fff; border-bottom: 1px solid #e2e8f0; }
._eg_band_top { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
._eg_band_k { flex: 0 0 auto; font: 800 10.5px/1.4 Inter, 'Segoe UI', system-ui, sans-serif; letter-spacing: .14em; text-transform: uppercase; color: #8a6d0f; }
._eg_band_req { flex: 1 1 auto; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font: 400 13px/1.3 Inter, 'Segoe UI', system-ui, sans-serif; color: #0f172a; }
._eg_band_segs { display: flex; gap: 4px; margin: 4px 0 3px; }
._eg_band_seg { flex: 1 1 0; height: 3px; background: #e2e8f0; }
._eg_band_seg._done { background: #c9a227; }
._eg_band_seg._on { background: #13294b; }
/* [BAND-LIVE] while the run works: a gold light runs along the step's segment, and the segment stands a little taller,
   so the top is never still (the owner, 10-22) */
._eg_band_live ._eg_band_seg._on { position: relative; overflow: hidden; height: 4px; margin-top: -1px; }
._eg_band_live ._eg_band_seg._on::after { content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 45%; background: linear-gradient(90deg, transparent, #f2d27a 50%, transparent); animation: _eg_band_run 1.5s cubic-bezier(.45, 0, .55, 1) infinite; }
@keyframes _eg_band_run { from { transform: translateX(-100%); } to { transform: translateX(230%); } }
._eg_band_step { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font: 600 12px/1.3 Inter, 'Segoe UI', system-ui, sans-serif; color: #13294b; }
._eg_band_n { font: 500 11.5px/1.3 Inter, 'Segoe UI', system-ui, sans-serif; color: #64748b; white-space: nowrap; }
._eg_body_chat ._eg_stage_strip, ._eg_body_chat ._eg_stage_step, ._eg_body_chat > ._eg_section_label:has(+ ._eg_instruction), ._eg_body_chat ._eg_instruction { display: none; }
._eg_body_chat ._eg_summary { padding: 0; margin: 4px 0 10px; background: none; border: 0; font: 400 14px/1.5 Inter, 'Segoe UI', system-ui, sans-serif; color: #334155; }
._eg_body_chat ._eg_prop_head { display: none; }   /* the band says "Your review · N changes"; the decision box, what needs you */
._eg_body_chat > ._eg_actions_row:last-child { position: sticky; bottom: 0; z-index: 5; margin: 10px -10px 0; padding: 10px; background: #fff; border-top: 1px solid #e2e8f0; }
/* ─── [TW-PAGE] Respond's deciding screen in the chat (Iris's L2, 10-21) ─── */
._eg_body_chat ._tw_a { background: transparent; border: 0; }
._eg_body_chat ._tw_band { position: static; margin: 0; padding: 0 0 8px; background: transparent; color: #13294b; }
._eg_body_chat ._tw_title, ._eg_body_chat ._tw_steps, ._eg_body_chat ._tw_ring { display: none; }
._eg_body_chat ._tw_sub { font: 500 12.5px/1.4 Inter, 'Segoe UI', system-ui, sans-serif; color: #475569; }
._eg_body_chat ._tw_band ._tw_clock { font: 600 14px/1 Inter, 'Segoe UI', system-ui, sans-serif; color: #13294b; }
._eg_body_chat ._tw_bar { margin: 0 0 10px; }
._eg_body_chat ._tw_spot { margin: 0 -10px 4px; padding: 12px 10px 14px; border: 0; border-bottom: 1px solid #ecdfae; background: #fbf3dd; }
._eg_body_chat ._tw_spot_h { font: 800 10.5px/1.4 Inter, 'Segoe UI', system-ui, sans-serif; letter-spacing: .14em; color: #8a6d0f; }
._eg_body_chat ._tw_spot_s { font: 600 13px/1.4 Inter, 'Segoe UI', system-ui, sans-serif; color: #334155; }
._eg_body_chat ._tw_spot_q { margin-top: 4px; font: 400 15px/1.45 Georgia, serif; color: #0f172a; }
._eg_body_chat ._tw_feed { padding: 12px 0 0; }
._eg_body_chat ._tw_feed_h { font: 800 10.5px/1.4 Inter, 'Segoe UI', system-ui, sans-serif; letter-spacing: .14em; color: #8a6d0f; }
._eg_body_chat ._tw_feed_h::after { content: " · newest first"; letter-spacing: .14em; }
._eg_body_chat ._tw_feed_list { overflow: visible; max-height: none; }
._eg_body_chat ._tw_dec { align-items: flex-start; gap: 10px; padding: 12px 0; border-top: 0; border-bottom: 1px solid #e2e8f0; }
._eg_body_chat ._tw_dec > ._eg_pv_dec { order: 2; margin-left: auto; flex: 0 0 auto; background: transparent; border: 1px solid #b0bcc6; border-radius: 0; color: #334155; padding: 2px 7px;
  font: 700 10.5px/1.4 Inter, 'Segoe UI', system-ui, sans-serif; letter-spacing: .1em; text-transform: uppercase; }
._eg_body_chat ._tw_dec > ._eg_pv_review { border-color: #c9a227; color: #8a6d0f; }
._eg_body_chat ._tw_dec_t { order: 1; flex: 1 1 auto; display: flex; flex-direction: column-reverse; font: 400 13.5px/1.45 Inter, 'Segoe UI', system-ui, sans-serif; color: #475569; }
._eg_body_chat ._tw_dec_s { margin-bottom: 2px; font: 400 15px/1.35 Georgia, serif; letter-spacing: 0; text-transform: none; color: #0f172a; }
._eg_band_replay { margin-left: 6px; padding: 1px 6px; border: 1px solid #c9a227; color: #8a6d0f; font-size: 9.5px; letter-spacing: .12em; }   /* [REPLAY] */
/* ─── [LOADER] the prelude: a seal breathing, the step in Georgia, a gold shimmer; navy in dark mode ─── */
._eg_prelude { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; min-height: 52vh; margin: 0 -10px; padding: 28px 18px; background: #fff; text-align: center; }
._eg_prelude_seal { width: 72px; height: 72px; overflow: visible; animation: _eg_breathe 2.4s ease-in-out infinite; }
._eg_prelude_arc { transform-box: fill-box; transform-origin: center; animation: _eg_turn 1.6s linear infinite; }
._eg_prelude_t { font: 400 19px/1.3 Georgia, serif; color: #13294b; }
._eg_prelude_s { max-width: 300px; font: 400 13px/1.45 Inter, 'Segoe UI', system-ui, sans-serif; color: #64748b; }
._eg_prelude_bar { position: relative; width: 160px; height: 2px; overflow: hidden; background: #ecdfae; }
._eg_prelude_bar i { position: absolute; top: 0; bottom: 0; width: 40%; background: linear-gradient(90deg, transparent, #c9a227, transparent); animation: _eg_shimmer 1.4s ease-in-out infinite; }
@keyframes _eg_breathe { 0%, 100% { filter: drop-shadow(0 0 2px rgba(201, 162, 39, .25)); } 50% { filter: drop-shadow(0 0 10px rgba(201, 162, 39, .6)); } }
@keyframes _eg_turn { to { transform: rotate(360deg); } }
@keyframes _eg_shimmer { 0% { left: -40%; } 100% { left: 100%; } }
body:not(.light-mode) ._eg_prelude { background: #0d1b2a; }
body:not(.light-mode) ._eg_prelude_t { color: #f7e08f; }
body:not(.light-mode) ._eg_prelude_s { color: #cbd5e1; }
body:not(.light-mode) ._eg_prelude_bar { background: rgba(201, 162, 39, .25); }
/* the review: what ELI checked, one closed line above the changes */
._eg_checked { margin: 6px 0 12px; border-top: 1px solid #e2e8f0; border-bottom: 1px solid #e2e8f0; }
._eg_checked > summary { cursor: pointer; padding: 9px 0; font: 600 13px/1.4 Inter, 'Segoe UI', system-ui, sans-serif; color: #13294b; }
._eg_checked[open] > summary { color: #8a6d0f; }
._eg_run_time { margin: 8px 0 2px; font: 400 12px/1.5 Inter, 'Segoe UI', system-ui, sans-serif; color: #64748b; }
/* [CALM-END] the run's details, folded under the team's sign-off */
._eg_calm_details { margin: 10px 0; }
._eg_calm_details > summary { cursor: pointer; font: 600 12px/1.4 'Inter', sans-serif; color: #475569; padding: 6px 0; }
._eg_calm_details[open] > summary { color: #13294b; }
/* [IN-PLACE] a card's clause edited where it stands, with Respond's editor (the owner, 10-22): the clause takes the
   cursor; open, the clause as it will read, ELI's words green on soft green as on the card; the clause's own size */
._eg_card_diff[data-eg-inplace] { position: relative; cursor: text; }
._eg_card_diff[data-eg-inplace]:hover { background: #f8fbf9; }
._eg_inplace { padding: 7px 9px; background: #fff; border: 1px solid #b9dfc6; font: 400 14px/1.5 Georgia, serif; color: #1f2937; white-space: pre-wrap; word-wrap: break-word; cursor: text; outline: none; }
._eg_inplace:focus { border-color: #15803d; box-shadow: 0 0 0 2px #dff3e6; }
._eg_inplace ins._eg_ours { color: #15803d; background: #e8f6ec; text-decoration: underline; text-decoration-color: #15803d; text-underline-offset: 2px; }
._eg_inplace_hint { margin-top: 5px; font: 500 11px/1.4 'Inter', sans-serif; color: #64748b; }
._eg_inplace_note { margin-top: 6px; padding: 5px 8px; background: #fffdf5; border: 1px solid #e8d89a; font: 500 11.5px/1.45 'Inter', sans-serif; color: #7a5b0c; }
/* the box's bottom-right corner: ✦ Ask (and, on Revise's cards, Reset ELI's wording) — the owner, 10-22; a strip kept
   for them under the last line, so the words never run beneath them */
._eg_inplace_box { position: relative; }
._eg_inplace_wrap ._eg_inplace, ._eg_inplace_wrap ._td_result, ._eg_inplace_wrap ._td_cmt_ta { padding-bottom: 30px; }
._eg_inplace_tools { position: absolute; bottom: 5px; right: 5px; display: flex; gap: 4px; }
._eg_inplace_ask_b { width: 22px; height: 21px; padding: 0; font: 600 12px/1 'Inter', sans-serif; color: #8a6d16; background: linear-gradient(180deg, #ffffff 0%, #fbf3d6 100%); border: 1px solid #c9a227; cursor: pointer; }
._eg_inplace_ask_b:hover { background: linear-gradient(180deg, #ffffff 0%, #f6e7b4 100%); }
._eg_ask_line { margin-top: 4px; }
._eg_ask_line input { box-sizing: border-box; width: 100%; padding: 5px 8px; font: 400 12.5px/1.3 'Inter', sans-serif; color: #0f172a; background: #fffdf6; border: 1px solid #c9a227; outline: none; }
._eg_inplace_reset_in { padding: 2px 6px; font: 600 10.5px/1.3 'Inter', sans-serif; color: #0d1b2a; background: linear-gradient(180deg, #ffffff 0%, #e8edf2 100%); border: 1px solid #b0bcc6; cursor: pointer; }
._eg_inplace_reset_in:hover { background: linear-gradient(180deg, #ffffff 0%, #dde3ea 100%); border-color: #94a3b8; }
/* [TD-COLOURS] Respond (the owner, 10-22): their changes are the subject — in Word's colours by reviewer (red, then violet,
   then teal), one reviewer one colour on every card. Once decided: accepted keeps the colour with a small check; what is
   decided against keeps a faded tinge of it (never gray: gray is Revise's background) — struck where their words go; a
   deletion rejected shows the words back, in ink, with a thin faded underline: restored. The key: as it was. */
._td_change .eli-clause ._td_other._td_au1, ._td_sub_words ._td_au1, ._td_au_chip._td_au1 { color: #c00000; }
._td_change .eli-clause ._td_other._td_au2, ._td_sub_words ._td_au2, ._td_au_chip._td_au2 { color: #7030a0; }
._td_change .eli-clause ._td_other._td_au3, ._td_sub_words ._td_au3, ._td_au_chip._td_au3 { color: #00806f; }
._td_change .eli-clause-key-old { color: #c00000; }
._td_card_reject ._td_change .eli-clause ins._td_other._td_focus, ._td_card_counter ._td_change .eli-clause ._td_other._td_focus,
._td_sub_reject ._td_sub_words ins._td_ins, ._td_sub_counter ._td_sub_words ._td_ins, ._td_sub_counter ._td_sub_words ._td_del { background: transparent; text-decoration-line: line-through; }
._td_card_reject ._td_change .eli-clause ins._td_other._td_focus._td_au1, ._td_card_counter ._td_change .eli-clause ._td_other._td_focus._td_au1, ._td_sub_reject ._td_sub_words ins._td_au1, ._td_sub_counter ._td_sub_words ._td_au1 { color: #de9b9b; }
._td_card_reject ._td_change .eli-clause ins._td_other._td_focus._td_au2, ._td_card_counter ._td_change .eli-clause ._td_other._td_focus._td_au2, ._td_sub_reject ._td_sub_words ins._td_au2, ._td_sub_counter ._td_sub_words ._td_au2 { color: #bb9bd3; }
._td_card_reject ._td_change .eli-clause ins._td_other._td_focus._td_au3, ._td_card_counter ._td_change .eli-clause ._td_other._td_focus._td_au3, ._td_sub_reject ._td_sub_words ins._td_au3, ._td_sub_counter ._td_sub_words ._td_au3 { color: #86c4ba; }
._td_card_reject ._td_change .eli-clause del._td_other._td_focus, ._td_sub_reject ._td_sub_words del._td_del { color: #1f2937; background: transparent; text-decoration-line: underline; text-decoration-thickness: 1px; text-underline-offset: 2px; }
._td_card_reject ._td_change .eli-clause del._td_other._td_focus._td_au1, ._td_sub_reject ._td_sub_words del._td_au1 { text-decoration-color: #de9b9b; }
._td_card_reject ._td_change .eli-clause del._td_other._td_focus._td_au2, ._td_sub_reject ._td_sub_words del._td_au2 { text-decoration-color: #bb9bd3; }
._td_card_reject ._td_change .eli-clause del._td_other._td_focus._td_au3, ._td_sub_reject ._td_sub_words del._td_au3 { text-decoration-color: #86c4ba; }
._td_card_accept ._td_change .eli-clause ._td_other._td_focus::after, ._td_sub_accept ._td_sub_words ._td_ins::after, ._td_sub_accept ._td_sub_words ._td_del::after {
  content: "\2713"; display: inline-block; margin-left: 2px; font: 700 10px/1 Inter, 'Segoe UI', sans-serif; color: #15803d; vertical-align: 2px; text-decoration: none; }
._td_au_chip { display: inline-block; margin-left: 6px; padding: 1px 3px; border: 1px solid currentColor; font: 700 9px/1 Inter, 'Segoe UI', sans-serif; letter-spacing: .06em; vertical-align: 1px; }
._td_result ins._td_eli_ctr, ._td_lock_ctr ins._td_eli_ctr { color: #15803d; background: #e8f6ec; text-decoration: underline; text-decoration-color: #15803d; text-underline-offset: 2px; }

/* [AI-TELLS] a quiet chip on a Respond card: their new words read as AI-drafted (a style, not proof) */
._td_ai { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px; margin: 4px 0 2px; font: 500 10.5px/1.35 'Inter', sans-serif; color: #475569; }
._td_ai_k { font-weight: 700; color: #7c5e10; background: #fdf6e3; border: 1px solid #ecd9a3; padding: 0 5px; }
._td_ai_lv { font-weight: 600; color: #64748b; }
._td_ai_why { color: #64748b; }
